            aPrevious = aIngress;
            //
            aIngress = (RotL64(aFuseLaneC[((aIndex + 31516U)) & S_BLOCK1], 19U) ^ RotL64(aFuseLaneA[((aIndex + 27680U)) & S_BLOCK1], 37U));
            aIngress ^= RotL64(aFireLaneC[((S_BLOCK1 - aIndex + 25276U)) & S_BLOCK1], 46U);
            aIngress = TwistMix64::DiffuseB((aIngress ^ aTwistDomainWordIngress));
