            aCross = (RotL64(aFuseLaneB[((S_BLOCK1 - aIndex + 32659U)) & S_BLOCK1], 5U) ^ RotL64(aWaterLaneD[((S_BLOCK1 - aIndex + 25623U)) & S_BLOCK1], 60U));
