            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterH = ((aWandererC + RotL64(aScatter, 11U)) + 0x9A925F8DCCEB3897ULL) + aTwistOrbiterAssignSaltE[(((255U - aIndex) + 25U)) & S_SALT1];
            aOrbiterB = (aWandererJ + RotL64(aIngress, 18U)) + 0x49E4689F8D1A66E6ULL;
            aOrbiterJ = ((aWandererE + RotL64(aCross, 29U)) + RotL64(aCarry, 19U)) + 0x7D0618BFA7025E4CULL;
            aOrbiterC = ((aWandererH + RotL64(aPrevious, 51U)) + RotL64(aCarry, 5U)) + 0xA94A471E05CBB748ULL;
            aOrbiterD = ((aWandererF + RotL64(aIngress, 35U)) + 0x75929696D7B80D68ULL) + aTwistOrbiterAssignSaltD[((aIndex + 173U)) & S_SALT1];
            aOrbiterI = ((aWandererK + RotL64(aScatter, 57U)) + RotL64(aCarry, 37U)) + 0xAD573F623EB6B8EAULL;
            aOrbiterG = (aWandererB + RotL64(aCross, 5U)) + 0x7404F2B6975D7991ULL;
            //
            aOrbiterH = (aOrbiterH + aOrbiterB) + 0xE36561323D369399ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0xEADBC055F5D97EA7ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x267F57B74F799B9FULL), 21U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterD) + 0x18E71EDC2C08F5B5ULL) + aTwistOrbiterUpdateSaltA[(((255U - aIndex) + 251U)) & S_SALT1];
