            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0xA1BF5FCDFB17E889ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterJ) ^ 0x8EAC1384B89295E9ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x80F4395508620DC5ULL), 27U);
