            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0xF64F44D4166A971BULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterB) ^ 0x45C36BD88B565D51ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x31B70B545EC5FBBFULL), 51U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterH) + 0x3B77B9B23E49ED3FULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterD) ^ 0x0A7AB7065F447DC6ULL) ^ aTwistOrbiterUpdateSaltF[(((255U - aIndex) + 75U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x4E232656F15FDABBULL), 43U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0xA4C6FA3CCFE1C4CEULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterG) ^ 0x964F1AD7D179328AULL) ^ aTwistOrbiterUpdateSaltE[(((255U - aIndex) + 161U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xE57306B82916D4EBULL), 11U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterG) + 0xA2BD7C720CDE677DULL) + aTwistOrbiterUpdateSaltD[((aIndex + 133U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterI) ^ 0x5552F5BDED027619ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xA302167168E8919DULL), 5U);
            //
            aIngress = RotL64(aOrbiterG, 21U) ^ aOrbiterB;
            aIngress = aIngress + (RotL64(aOrbiterH, 27U) ^ aOrbiterD);
