            aIngress = aIngress + RotL64(aOrbiterC, 60U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererJ = aWandererJ + (((RotL64(aScatter, 5U) + RotL64(aOrbiterB, 21U)) + aOrbiterJ) + RotL64(aCarry, 35U));
            aWandererB = aWandererB ^ ((RotL64(aIngress, 29U) + aOrbiterH) + RotL64(aOrbiterJ, 35U));
            aWandererF = aWandererF + (((RotL64(aCross, 23U) + RotL64(aOrbiterG, 41U)) + aOrbiterC) + aTwistWandererUpdateSaltE[(((255U - aIndex) + 187U)) & S_SALT1]);
            aWandererE = aWandererE ^ ((RotL64(aPrevious, 50U) + aOrbiterG) + RotL64(aOrbiterJ, 29U));
            aWandererC = aWandererC + (((RotL64(aIngress, 37U) + RotL64(aOrbiterD, 47U)) + aOrbiterB) + RotL64(aCarry, 21U));
            aWandererK = aWandererK ^ ((RotL64(aCross, 11U) + RotL64(aOrbiterI, 13U)) + aOrbiterG);
            aWandererH = aWandererH + (((RotL64(aPrevious, 43U) + aOrbiterC) + RotL64(aOrbiterD, 60U)) + aTwistWandererUpdateSaltC[((aIndex + 255U)) & S_SALT1]);
