            aOrbiterJ = ((aOrbiterJ ^ aOrbiterC) ^ 0xAAE3E1664949F957ULL) ^ aKeyRotateAOrbiterUpdateSaltE[(((255U - aIndex) + 252U)) & S_SALT1];
